"""TidyBot sensor-guided controller, using only documented client sensors/actions.
All executed action rows are saved to actions.jsonl; run replay for exact playback.
"""
from rcb_client import Robot
import json, argparse
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image
OUT=Path('/app/output'); OUT.mkdir(exist_ok=True)
S=json.loads((OUT/'spec.json').read_text())
P=np.array(S['arm']['position_m']); AX=np.array(S['arm']['axis'])
EE=np.array(S['arm']['end_effector']['position_m'])
CP=np.array(S['cameras']['robot_wrist']['pose']['position_m'])

def fk(q,base=None):
    R=np.eye(3); t=np.zeros(3)
    for a,p,theta in zip(AX,P,q):
        d=Rotation.from_rotvec(a*theta).as_matrix()
        t=t+R@(p-d@p); R=R@d
    if base is not None:
        B=Rotation.from_euler('z',base[2]).as_matrix()
        t=B@t+np.r_[base[:2],0]; R=B@R
    return R,t

def pose(v):
    R,t=fk(v[6:13],v[:3]); return R@EE+t,R

def ik(xyz,Rgoal,q,base):
    def err(v):
        R,t=fk(v,base)
        return np.r_[(R@EE+t-xyz)*5,Rotation.from_matrix(Rgoal@R.T).as_rotvec(),0.008*(v-q)]
    lo=np.full(7,-20.); hi=-lo
    for i,lim in enumerate(S['arm']['limits_rad']):
        if lim: lo[i],hi[i]=lim
    sol=least_squares(err,np.clip(q,lo+1e-6,hi-1e-6),bounds=(lo,hi),max_nfev=200)
    R,t=fk(sol.x,base)
    return sol.x,np.linalg.norm(R@EE+t-xyz),np.linalg.norm(Rotation.from_matrix(Rgoal@R.T).as_rotvec())

class Driver:
    def __init__(self): self.r=Robot(); self.res=self.r.get_obs(include_depth=True,video='none'); self.v=np.array(self.res.meta['proprio']['now'])
    def save(self,label='latest'):
        d=OUT/label; self.res.save(d)
        for c,im in self.res.last.items(): Image.fromarray(im).save(d/(c+'.png'))
        (OUT/'latest_state.json').write_text(json.dumps(self.res.meta))
    def act(self,a,note=''):
        a=np.array(a); a=a[None] if a.ndim==1 else a
        with (OUT/'actions.jsonl').open('a') as f: f.write(json.dumps({'actions':a.tolist(),'note':note})+'\n')
        self.res=self.r.submit('delta',a,include_depth=True,video='none',note=note)
        self.v=np.array(self.res.meta['proprio']['now'])
        if self.res.done: self.save(); print(self.res.meta); raise SystemExit
        return self.res
    def joint(self,q,grip=0,steps=60,tol=.008):
        for k in range(steps):
            e=np.array(q)-self.v[6:13]
            if np.max(abs(e))<tol: break
            a=np.zeros(11); a[3:10]=np.clip(e,-.09,.09); a[10]=grip
            self.act(a,'joint servo')
        self.save(); print('joint',k,'error',e.round(4),'pose',pose(self.v)[0].round(4),'steps',self.res.meta['control_steps'])
    def move(self,xyz,Rgoal=None,grip=0,steps=60):
        if Rgoal is None: Rgoal=pose(self.v)[1]
        q,err,rot=ik(np.array(xyz),Rgoal,self.v[6:13],self.v[:3]); print('IK',q.round(4),err,rot)
        if err>.008 or rot>.03: raise ValueError('Unreachable pose')
        self.joint(q,grip,steps)
    def line(self,xyz,grip=0,speed=.018,Rgoal=None):
        start,R=pose(self.v); Rgoal=R if Rgoal is None else Rgoal
        n=int(np.ceil(np.linalg.norm(np.array(xyz)-start)/speed))
        for x in np.linspace(start,xyz,n+1)[1:]:
            q,err,rot=ik(x,Rgoal,self.v[6:13],self.v[:3])
            if err>.015: raise ValueError(f'line IK {err}')
            a=np.zeros(11); a[3:10]=np.clip(q-self.v[6:13],-.1,.1); a[10]=grip; self.act(a,'cartesian line')
        self.move(xyz,Rgoal,grip,15)
    def grip(self,g,n=5):
        a=np.zeros((n,11)); a[:,10]=g; self.act(a,'gripper'); self.save(); print('gripper',self.v[20], 'pose',pose(self.v)[0], 'steps',self.res.meta['control_steps'])
    def base(self,delta,grip=0):
        target=self.v[:3]+delta
        for k in range(80):
            e=target-self.v[:3]
            if np.max(abs(e))<.004:break
            a=np.zeros(11); a[:3]=np.clip(e,-.065,.065); a[10]=grip; self.act(a,'base servo')
        self.save(); print('base',self.v[:3], 'pose',pose(self.v)[0], 'steps',self.res.meta['control_steps'])
    def pixel(self,u,v):
        dep=self.res.depth['robot_wrist'][-1]; z=float(dep[v,u]); f=240/np.tan(np.deg2rad(41.8/2))
        # camera x image right = -X, image down=-Y, forward=Z in rest coordinates
        p=CP+np.array([-(u-319.5)*z/f,-(v-239.5)*z/f,z]); R,t=fk(self.v[6:13],self.v[:3])
        return z,R@p+t
    def report(self):
        print(self.res.meta); print('EE',pose(self.v)); print('camera',fk(self.v[6:13],self.v[:3])[0]@CP+fk(self.v[6:13],self.v[:3])[1]); self.save()

if __name__=='__main__':
    p=argparse.ArgumentParser(); p.add_argument('cmd',nargs='?',default='obs'); p.add_argument('values',nargs='*',type=float); p.add_argument('--grip',type=float,default=0); p.add_argument('--rot',nargs=3,type=float); p.add_argument('--steps',type=int,default=60); a=p.parse_args()
    d=Driver()
    R=Rotation.from_euler('xyz',a.rot).as_matrix() if a.rot else None
    if a.cmd=='obs': d.report()
    elif a.cmd=='joint':d.joint(a.values,a.grip,a.steps)
    elif a.cmd=='move':d.move(a.values,R,a.grip,a.steps)
    elif a.cmd=='line':d.line(a.values,a.grip,Rgoal=R)
    elif a.cmd=='base':d.base(np.array(a.values),a.grip)
    elif a.cmd=='grip':d.grip(a.values[0],int(a.values[1]) if len(a.values)>1 else 5)
    elif a.cmd=='pixel':
        for u,v in np.array(a.values,dtype=int).reshape(-1,2):print(u,v,d.pixel(u,v))
    elif a.cmd=='replay':
        rows=[json.loads(x) for x in (OUT/'actions.jsonl').read_text().splitlines()]
        for row in rows:d.r.submit('delta',row['actions'],note=row['note'],video='none')
PY
